#include <string.h>

// helper function to add two numbers
int add(int a, int b) {
    // return a + b
    return (a + b);
}

int charge_steps(int level, int target) {
    // create variable steps and initialize to 0
    int steps = 0;
    // loop while level is less than target
    while (level < target) {
        // call add to increase level by 7
        level = add(level, 7);
        // increment steps by 1
        steps = steps + 1;
        // loop will end automatically
    }
    // return the number of steps
    return steps;
}
